# AgentGuard endpoint one-click __AG_ACTION__ (Windows), generated by the AgentGuard server.
#
#   irm __AG_URL__/v1/agents/install.ps1 | iex       # install
#   irm __AG_URL__/v1/agents/uninstall.ps1 | iex     # uninstall (or: Settings > Apps > AgentGuard Endpoint)
#
# Downloads the client from the server into a temporary directory and runs it:
#   setup      installs hooks for the agents configured in the console (Devices > Client deployment),
#              applies for enrollment, waits for approval and runs a self-test;
#   uninstall  removes AgentGuard hooks of all agents, client files and the host token.
# Uses `return` rather than `exit`: when run through iex, exit would close the caller's PowerShell window.
& {
    $ErrorActionPreference = 'Stop'
    $AgUrl = '__AG_URL__'
    $AgScope = '__AG_SCOPE__'
    $AgAction = '__AG_ACTION__'
    $AgPackage = '__AG_WINDOWS_PACKAGE__'
    if (-not $AgPackage) {
        Write-Host 'error: the server has not published the Windows client (endpoint/dist/agentguard-endpoint-windows-x64.zip)' -ForegroundColor Red
        return
    }
    $identity = [Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()
    $admin = $identity.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
    if ($AgAction -eq 'setup' -and $AgScope -eq 'machine' -and -not $admin) {
        Write-Host 'The deployment is machine-wide (all users): requesting administrator rights...'
        $command = "[Net.WebRequest]::DefaultWebProxy = `$null; irm '$AgUrl/v1/agents/install.ps1' | iex"
        Start-Process powershell.exe -Verb RunAs -ArgumentList '-NoProfile', '-ExecutionPolicy', 'Bypass', '-NoExit', '-Command', $command
        return
    }
    $tmp = Join-Path ([IO.Path]::GetTempPath()) ('agentguard-' + [Guid]::NewGuid().ToString('N').Substring(0, 8))
    New-Item -ItemType Directory -Path $tmp | Out-Null
    try {
        $zip = Join-Path $tmp 'client.zip'
        $web = New-Object Net.WebClient
        $web.Proxy = $null   # the client talks to the server directly; download the same way
        $web.DownloadFile("$AgUrl/v1/agents/client/$AgPackage", $zip)
        Expand-Archive -Path $zip -DestinationPath $tmp -Force
        $exe = Join-Path $tmp 'agentguard-endpoint\agentguard-endpoint.exe'
        if ($AgAction -eq 'setup') { & $exe setup --url $AgUrl } else { & $exe uninstall --all --purge --url $AgUrl }
        if ($LASTEXITCODE) { Write-Host "AgentGuard $AgAction failed (exit code $LASTEXITCODE)" -ForegroundColor Red }
    } finally {
        Remove-Item -Recurse -Force $tmp -ErrorAction SilentlyContinue
    }
}
